def largest_perimeter_brute(nums):
    n = len(nums)
    best = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):                     # check every triple directly
                a, b, c = sorted([nums[i], nums[j], nums[k]])
                if a + b > c:
                    best = max(best, a + b + c)
    return best

