import java.util.*;

public class Main {
    static int largestPerimeterBrute(int[] nums) {
        int n = nums.length, best = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                for (int k = j + 1; k < n; k++) {                    // check every triple directly
                    int[] t = {nums[i], nums[j], nums[k]};
                    Arrays.sort(t);
                    if (t[0] + t[1] > t[2]) best = Math.max(best, t[0] + t[1] + t[2]);
                }
        return best;
    }
}

