def largest_perimeter(nums):
    nums.sort(reverse=True)                              # sort descending
    for i in range(len(nums) - 2):
        if nums[i] < nums[i + 1] + nums[i + 2]:            # first valid adjacent triple
            return nums[i] + nums[i + 1] + nums[i + 2]
    return 0

