import java.util.*;

public class Main {
    static int largestPerimeter(int[] nums) {
        Integer[] boxed = Arrays.stream(nums).boxed().toArray(Integer[]::new);
        Arrays.sort(boxed, Collections.reverseOrder());       // sort descending
        for (int i = 0; i < boxed.length - 2; i++) {
            if (boxed[i] < boxed[i + 1] + boxed[i + 2]) {          // first valid adjacent triple
                return boxed[i] + boxed[i + 1] + boxed[i + 2];
            }
        }
        return 0;
    }
}

